def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    import math
    import statistics
    h = max(0, int(horizon))
    if h == 0:
        return []
    y = []
    for value in history:
        try:
            value = float(value)
            if math.isfinite(value):
                y.append(value)
        except (TypeError, ValueError):
            pass
    if not y:
        return [0.0] * h
    if len(y) < 24:
        return [float(statistics.median(y[-min(7, len(y)):]))] * h

    def smape(actual, predicted):
        errors = []
        for a, b in zip(actual, predicted):
            scale = abs(a) + abs(b)
            if scale > 1e-12:
                errors.append(200.0 * abs(a - b) / scale)
        return sum(errors) / len(errors) if errors else 0.0

    def make_prediction(train, steps, period, blend, drift_weight):
        if period <= 1 or len(train) < 2 * period:
            return [float(statistics.median(train[-min(5, len(train)):]))] * steps
        recent = train[-period:]
        previous = train[-2 * period:-period]
        level_shift = statistics.median(recent) - statistics.median(previous)
        differences = [train[i] - train[i - 1] for i in range(1, len(train))]
        local = differences[-min(2 * period, len(differences)):]
        center = statistics.median(local) if local else 0.0
        mad = statistics.median([abs(v - center) for v in local]) if local else 0.0
        cap = max(1e-6, 3.0 * mad * math.sqrt(period))
        level_shift = max(-cap, min(cap, level_shift))
        out = []
        for k in range(steps):
            phase = k % period
            cycle = k // period
            adjusted_previous = previous[phase] + level_shift
            base = blend * recent[phase] + (1.0 - blend) * adjusted_previous
            drift = drift_weight * level_shift * (1.0 - 0.5 ** (cycle + 1))
            out.append(float(base + drift))
        return out

    block = min(36, max(12, len(y) // 8))
    folds = []
    for back in range(4, 0, -1):
        cut = len(y) - back * block
        if cut >= 72:
            folds.append((y[:cut], y[cut:cut + block]))
    max_period = min(120, len(y) // 2)
    periods = [1] + list(range(36, max_period + 1))
    candidates = []
    for period in periods:
        for blend in ((1.0,) if period == 1 else (0.5, 0.75, 1.0)):
            for drift_weight in ((0.0,) if period == 1 else (0.0, 0.25, 0.5)):
                errors = []
                for train, actual in folds:
                    if period > 1 and len(train) < 2 * period:
                        errors = []
                        break
                    estimate = make_prediction(train, len(actual), period, blend, drift_weight)
                    errors.append(smape(actual, estimate))
                if errors:
                    risk = statistics.median(errors) + 0.35 * max(errors)
                    candidates.append((risk, max(errors), period, blend, drift_weight))
    if not candidates:
        return [float(statistics.median(y[-5:]))] * h
    _, _, period, blend, drift_weight = min(candidates)
    return make_prediction(y, h, period, blend, drift_weight)

def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    import math
    import statistics
    h = max(0, int(horizon))
    if h == 0:
        return []
    y = []
    for value in history:
        try:
            value = float(value)
            if math.isfinite(value):
                y.append(value)
        except (TypeError, ValueError):
            pass
    if not y:
        return [0.0] * h
    if len(y) < 20:
        return [float(statistics.median(y[-min(5, len(y)):]))] * h

    def smape(actual, predicted):
        errors = []
        for a, b in zip(actual, predicted):
            scale = abs(a) + abs(b)
            if scale > 1e-12:
                errors.append(200.0 * abs(a - b) / scale)
        return sum(errors) / len(errors) if errors else 0.0

    def analog_predict(train, steps, context, neighbors, persistence_weight):
        original = list(train)
        generated = list(train)
        center = statistics.median(original)
        mad = statistics.median([abs(v - center) for v in original])
        lower = min(original) - 2.0 * mad
        upper = max(original) + 2.0 * mad
        for _ in range(steps):
            query = generated[-context:]
            qmean = sum(query) / context
            qscale = math.sqrt(sum((v - qmean) ** 2 for v in query) / context)
            qscale = max(qscale, 1e-6)
            matches = []
            for end in range(context, len(original)):
                window = original[end - context:end]
                wmean = sum(window) / context
                wscale = math.sqrt(sum((v - wmean) ** 2 for v in window) / context)
                wscale = max(wscale, 1e-6)
                distance = math.sqrt(sum((((query[j] - qmean) / qscale) - ((window[j] - wmean) / wscale)) ** 2 for j in range(context)) / context)
                continuation = qmean + (original[end] - wmean) * qscale / wscale
                matches.append((distance, continuation))
            matches.sort(key=lambda item: item[0])
            chosen = matches[:neighbors]
            if not chosen or chosen[0][0] > 1.5:
                estimate = generated[-1]
            else:
                weights = [1.0 / max(1e-6, item[0]) for item in chosen]
                analog = sum(w * item[1] for w, item in zip(weights, chosen)) / sum(weights)
                estimate = persistence_weight * generated[-1] + (1.0 - persistence_weight) * analog
            generated.append(float(max(lower, min(upper, estimate))))
        return generated[-steps:]

    block = min(30, max(10, len(y) // 9))
    folds = []
    for back in range(4, 0, -1):
        cut = len(y) - back * block
        if cut >= 50:
            folds.append((y[:cut], y[cut:cut + block]))
    candidates = []
    for context in (8, 12, 16, 24):
        for neighbors in (1, 3, 5):
            for persistence_weight in (0.0, 0.25, 0.5, 0.75):
                errors = []
                for train, actual in folds:
                    if len(train) <= context + neighbors:
                        errors = []
                        break
                    estimate = analog_predict(train, len(actual), context, neighbors, persistence_weight)
                    errors.append(smape(actual, estimate))
                if errors:
                    risk = statistics.median(errors) + 0.25 * max(errors)
                    candidates.append((risk, context, neighbors, persistence_weight))
    persistence_errors = [smape(actual, [train[-1]] * len(actual)) for train, actual in folds]
    persistence_risk = statistics.median(persistence_errors) + 0.25 * max(persistence_errors) if persistence_errors else float('inf')
    if not candidates:
        return [float(y[-1])] * h
    risk, context, neighbors, persistence_weight = min(candidates)
    if risk >= persistence_risk:
        return [float(y[-1])] * h
    return analog_predict(y, h, context, neighbors, persistence_weight)
